import sys

import pytest

import flask
from flask.testing import FlaskClient


def test_teardown_request_reverse_order_and_exception(
    app: flask.Flask, client: FlaskClient
) -> None:
    app.config["PROPAGATE_EXCEPTIONS"] = False
    view_error = ValueError("view error")
    calls: list[tuple[str, BaseException | None]] = []

    @app.teardown_request
    def teardown_1(exc: BaseException | None) -> None:
        calls.append(("teardown_1", exc))

    @app.teardown_request
    def teardown_2(exc: BaseException | None) -> None:
        calls.append(("teardown_2", exc))

    @app.teardown_request
    def teardown_3(exc: BaseException | None) -> None:
        calls.append(("teardown_3", exc))

    @app.route("/")
    def index() -> str:
        raise view_error

    response = client.get("/")
    assert response.status_code == 500
    assert calls == [
        ("teardown_3", view_error),
        ("teardown_2", view_error),
        ("teardown_1", view_error),
    ]
    assert all(exc is view_error for _, exc in calls)


def test_teardown_request_continues_after_error(
    app: flask.Flask, client: FlaskClient
) -> None:
    app.config["PROPAGATE_EXCEPTIONS"] = False
    view_error = ValueError("view error")
    teardown_error = RuntimeError("teardown_2 error")
    calls: list[tuple[str, BaseException | None]] = []

    @app.teardown_request
    def teardown_1(exc: BaseException | None) -> None:
        calls.append(("teardown_1", exc))

    @app.teardown_request
    def teardown_2(exc: BaseException | None) -> None:
        calls.append(("teardown_2", exc))
        raise teardown_error

    @app.teardown_request
    def teardown_3(exc: BaseException | None) -> None:
        calls.append(("teardown_3", exc))

    @app.route("/")
    def index() -> str:
        raise view_error

    if sys.version_info >= (3, 11):
        with pytest.raises(
            ExceptionGroup, match="Errors during context teardown"  # noqa: F821
        ) as exc_info:
            client.get("/")

        assert calls == [
            ("teardown_3", view_error),
            ("teardown_2", view_error),
            ("teardown_1", view_error),
        ]
        assert all(exc is view_error for _, exc in calls)
        assert len(exc_info.value.exceptions) == 1
        req_exc_group = exc_info.value.exceptions[0]
        assert isinstance(req_exc_group, ExceptionGroup)  # noqa: F821
        assert req_exc_group.message == "Errors during request teardown"
        assert req_exc_group.exceptions == (teardown_error,)
    else:
        with pytest.raises(RuntimeError, match="teardown_2 error") as exc_info:
            client.get("/")

        assert calls == [
            ("teardown_3", view_error),
            ("teardown_2", view_error),
            ("teardown_1", view_error),
        ]
        assert all(exc is view_error for _, exc in calls)
        assert exc_info.value is teardown_error

import { Hono } from '../../hono'
import { MESSAGE_MATCHER_IS_ALREADY_BUILT } from '../../router'

describe('SmartRouter with default Hono app', () => {
  it('uses RegExpRouter when only ordinary routes are registered', async () => {
    const app = new Hono()
    app.get('/hello', (c) => c.text('hello'))
    app.get('/users/:id', (c) => c.text(`user:${c.req.param('id')}`))

    const res1 = await app.request('/hello')
    expect(res1.status).toBe(200)
    expect(await res1.text()).toBe('hello')

    const res2 = await app.request('/users/42')
    expect(res2.status).toBe(200)
    expect(await res2.text()).toBe('user:42')

    expect(app.router.name).toBe('SmartRouter + RegExpRouter')
  })

  it('falls back to TrieRouter when a route RegExpRouter cannot handle is registered and answers requests correctly', async () => {
    const app = new Hono()
    app.get('/hello', (c) => c.text('hello'))
    app.get('/files/:name{.*}', (c) => c.text(`file:${c.req.param('name')}`))
    app.get('/:user/entries', (c) => c.text(`user:${c.req.param('user')}`))
    app.get('/entry/:name', (c) => c.text(`entry:${c.req.param('name')}`))

    const res1 = await app.request('/hello')
    expect(res1.status).toBe(200)
    expect(await res1.text()).toBe('hello')
    expect(app.router.name).toBe('SmartRouter + TrieRouter')

    const res2 = await app.request('/files/dir/sub/doc.txt')
    expect(res2.status).toBe(200)
    expect(await res2.text()).toBe('file:dir/sub/doc.txt')

    const res3 = await app.request('/alice/entries')
    expect(res3.status).toBe(200)
    expect(await res3.text()).toBe('user:alice')

    const res4 = await app.request('/entry/first')
    expect(res4.status).toBe(200)
    expect(await res4.text()).toBe('entry:first')
  })

  it('throws an error when adding a route after the first request has been handled', async () => {
    const app = new Hono()
    app.get('/hello', (c) => c.text('hello'))

    const res = await app.request('/hello')
    expect(res.status).toBe(200)
    expect(await res.text()).toBe('hello')

    expect(() => {
      app.get('/other', (c) => c.text('other'))
    }).toThrowError(new Error(MESSAGE_MATCHER_IS_ALREADY_BUILT))
  })
})

